/bin/zsh -lc "python -c \"import pandas as pd,numpy as np; from scipy.special import expit; d=pd.read_csv('data/nls_ses_processed.csv'); x=d.SES.to_numpy(); y=d['BA DEGREE COMPLETED'].astype(float).to_numpy();
for b in [0.47293096,0.5129]:
 a=-3.645 if b<.5 else -3.68; p=expit(a+b*x); print(a,b,(p-y).sum(),x@(p-y))\""

